ORDER BY RECORD_TIME DESC

SELECT COUNT(*)
FROM ALERT
WHERE ALERT_STATUS = 0

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}

SELECT 
    EXTRACT(HOUR FROM RECORD_TIME) as hour,
    COUNT(*) as count
FROM ALERT


        AND TOURISM_NAME = #{tourismName}


        AND DEVICE_CODE = #{deviceCode}


        AND RECORD_TIME >= #{startTime}


        AND RECORD_TIME <= #{endTime}


GROUP BY EXTRACT(HOUR FROM RECORD_TIME)
ORDER BY hour

SELECT 
    ALERT_TYPE as type,
    COUNT(*) as count
FROM ALERT


        AND TOURISM_NAME = #{tourismName}


        AND DEVICE_CODE = #{deviceCode}


        AND RECORD_TIME >= #{startTime}


        AND RECORD_TIME <= #{endTime}


GROUP BY ALERT_TYPE

SELECT 
    ALERT_LEVEL as level,
    COUNT(*) as count
FROM ALERT


        AND TOURISM_NAME = #{tourismName}


        AND DEVICE_CODE = #{deviceCode}


        AND RECORD_TIME >= #{startTime}


        AND RECORD_TIME <= #{endTime}


GROUP BY ALERT_LEVEL
ORDER BY level

