INSERT INTO ALERT ( TOURISM_NAME, DEVICE_CODE, DEVICE_NAME, ALERT_TYPE, ALERT_LEVEL, ALERT_STATUS, DESCRIPTION, IMAGE_URL, RECORD_TIME, CREATE_TIME, UPDATE_TIME ) SELECT A.*, SYSTIMESTAMP, SYSTIMESTAMP FROM (
SELECT #{item.tourismName}, #{item.deviceCode}, #{item.deviceName}, #{item.alertType}, #{item.alertLevel}, #{item.alertStatus}, #{item.description}, #{item.imageUrl}, #{item.recordTime} FROM DUAL
) A

