SELECT 
    TO_CHAR(RECORD_TIME, 'YYYY-MM-DD HH24') as time,
    COUNT(*) as count
FROM ALERT


        AND TOURISM_NAME = #{tourismName}


        AND DEVICE_CODE = #{deviceCode}


        AND RECORD_TIME >= #{startTime}


        AND RECORD_TIME <= #{endTime}


GROUP BY TO_CHAR(RECORD_TIME, 'YYYY-MM-DD HH24')
ORDER BY time

SELECT 
    COUNT(*) as total,
    COUNT(CASE WHEN ALERT_STATUS = 0 THEN 1 END) as pending,
    COUNT(CASE WHEN ALERT_STATUS = 1 THEN 1 END) as handled,
    COUNT(CASE WHEN ALERT_LEVEL = 1 THEN 1 END) as lowLevel,
    COUNT(CASE WHEN ALERT_LEVEL = 2 THEN 1 END) as mediumLevel,
    COUNT(CASE WHEN ALERT_LEVEL = 3 THEN 1 END) as highLevel
FROM ALERT


        AND TOURISM_NAME = #{tourismName}


        AND DEVICE_CODE = #{deviceCode}


        AND RECORD_TIME >= #{startTime}


        AND RECORD_TIME <= #{endTime}
